/* eslint-disable react/require-default-props */
import { Home } from '@hexa-ui/icons';
import { Slot } from '@radix-ui/react-slot';
import React from 'react';
import {
  HomeLinkContainer,
  HomeLinkDefault,
  HomeLinkSlot,
  List,
  ListItem,
  Separator,
} from './Breadcrumb.styles';

export const Breadcrumb = ({ children }: { children: React.ReactNode }): JSX.Element => (
  <nav>
    <List>{children}</List>
  </nav>
);

export interface BreadcrumbHomeItemProps {
  asChild?: boolean;
  href?: string;
  children?: React.ReactNode;
  ariaLabel?: string;
}

export const HomeItem = ({
  asChild = false,
  ariaLabel = 'link to home',
  ...props
}: BreadcrumbHomeItemProps): JSX.Element => {
  const Comp = asChild ? HomeLinkSlot : HomeLinkDefault;
  return (
    <ListItem css={{ marginLeft: 0 }}>
      <HomeLinkContainer>
        <Comp aria-label={ariaLabel} {...props} />
        <Home />
      </HomeLinkContainer>
      <Separator size="medium" />
    </ListItem>
  );
};

export interface BreadcrumbItemProps {
  isCurrentPage?: boolean;
  asChild?: boolean;
  children: React.ReactNode;
  href?: string;
}

export const Item = ({
  isCurrentPage = false,
  asChild = false,
  ...props
}: BreadcrumbItemProps): JSX.Element => {
  const Comp = asChild ? Slot : 'a';
  return isCurrentPage ? (
    <ListItem isCurrentPage {...props} />
  ) : (
    <ListItem>
      <Comp {...props} />
      <Separator size="medium" />
    </ListItem>
  );
};
